shell_commands:
node --input-type=module -e '
import reLint from "@re-cinq/eslint-plugin-re-lint";
for (const name of ["require-colocated-tests", "test-imports-its-subject", "require-spec-link", "max-expects", "no-nondeterministic-tests"]) {
  console.log("=== " + name + " ===");
  console.log(reLint.rules[name].create.toString());
}
'

node --input-type=module -e '
import { createRequire } from "node:module";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
const req = createRequire(import.meta.url);
const pkgPath = req.resolve("@re-cinq/eslint-plugin-re-lint");
const dir = dirname(pkgPath);
console.log("Plugin dir:", dir);
for (const f of ["rules/require-spec-link.js", "rules/require-status-matches-coverage.js", "rules/no-vague-names.js", "rules/no-negative-names.js", "rules/callee-below-caller.js", "rules/declare-near-use.js", "rules/max-member-chain.js"]) {
  try {
    console.log("=== " + f + " ===");
    console.log(readFileSync(join(dir, f), "utf8").slice(0, 2500));
  } catch (e) {
    console.log(f, e.message);
  }
}
'

node --input-type=module -e '
import reLint from "@re-cinq/eslint-plugin-re-lint";
for (const [name, rule] of Object.entries(reLint.rules)) {
  console.log(name, "->", JSON.stringify(rule.meta?.messages ?? {}));
}
'

node --input-type=module -e '
import { createRequire } from "node:module";
import { readdirSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
const req = createRequire(import.meta.url);
const dir = dirname(req.resolve("@re-cinq/eslint-plugin-re-lint"));
console.log("Files in dist:", readdirSync(dir));
const idx = readFileSync(join(dir, "index.js"), "utf8");
for (const term of ["VAGUE", "noComments", "maxDistance", "calleeAboveCaller", "chainTooDeep", "negativeName", "statusMismatch"]) {
  const pos = idx.indexOf(term);
  console.log("=== " + term + " ===");
  if (pos >= 0) console.log(idx.slice(Math.max(0, pos - 600), pos + 800));
}
'

node --input-type=module -e '
import { createRequire } from "node:module";
import { readFileSync } from "node:fs";
